# Les 2 seuls ISBN vérifiés par l'utilisateur à conserver
VERIFIED_ISBNS = {
    "fab5b7de-31d5-470a-9066-f98f84c089b7": "9782381961903",  # Watership Down
    "4b4b0eec-70db-4dd0-a31e-465dff7a88ca": "9791034768974",  # Soli Deo Gloria
}

async def restore():
    print("Restauration des 102 alertes à leur état d'origine propre...")
    async with AsyncSessionLocal() as session:
        for alert_id, name, url in ORIGINAL_DATA:
            isbn = VERIFIED_ISBNS.get(alert_id)
            await session.execute(
                text("UPDATE alerts SET vinted_search_url = :url, isbn = :isbn WHERE id = :id"),
                {"url": url, "isbn": isbn, "id": alert_id}
            )
        await session.commit()
    print("Restauration terminée !")

if __name__ == "__main__":
    asyncio.run(restore())
